/* Udaan reel — shared design engine.
 * Used by BOTH the builder preview (builder/index.html) and the render composition
 * (index.html, generated by scripts/build_index.cjs). One source of truth: what you
 * see in the builder is what renders.
 *
 *   markup(project, base)        -> HTML string for everything inside the root div
 *   buildTimeline(tl, project)   -> adds every tween to a paused GSAP timeline
 *   css(base)                    -> stylesheet string
 *   DESIGNS / ACCENTS / MOTIONS / TRANSITIONS -> catalogs (name, desc, html, anim)
 *   suggest(beat)                -> >= 3 design ids that suit this beat
 */
(function (root) {
  "use strict";
  const NAVY = "#14213D", RED = "#D7192A";

  // ---------- helpers ----------
  const esc = (s) => String(s == null ? "" : s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const lines = (b) => (b.text || []).map((s) => String(s).trim()).filter(Boolean);
  const hash = (s) => { let h = 2166136261; for (const c of String(s)) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return h >>> 0; };
  function rng(seed) { // mulberry32 — deterministic
    return function () { seed |= 0; seed = (seed + 0x6d2b79f5) | 0; let t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  }
  // font size that fits `text` in `budget` px (Barlow Condensed 800 ≈ 0.47em per char)
  const fit = (text, max, budget = 940) => Math.max(56, Math.min(max, Math.floor(budget / (Math.max(1, text.length) * 0.47))));

  function withDur(P) {
    const B = P.beats.slice().sort((a, b) => a.start - b.start);
    return B.map((b, i) => Object.assign({}, b, { dur: +(((i + 1 < B.length ? B[i + 1].start : P.meta.duration) - b.start).toFixed(3)), index: i }));
  }

  // =====================================================================
  // TEXT DESIGNS (main headline treatments)
  // =====================================================================
  const DESIGNS = {
    none: { name: "Clean", kind: "none", desc: "No headline — let the shot (or its burned-in text) breathe.", html: () => "", anim: () => {} },

    slam: {
      name: "Slam", kind: "text", desc: "One giant word slams in, screen shakes, red slash underline.",
      html: (b, u) => { const t = lines(b).join(" ") || "SLAM"; return `<div class="d-center d-slam"><div class="w" id="${u}-w" style="font-size:${fit(t, 260)}px">${esc(t)}</div><div class="bar" id="${u}-bar"></div></div>`; },
      anim: (tl, u, t0) => {
        tl.fromTo(`#${u}-w`, { scale: 2.6, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.18, ease: "power4.in" }, t0 + 0.04);
        tl.fromTo(`#${u}-w`, { x: 0, y: 0 }, { keyframes: [{ x: -16, y: 6 }, { x: 12, y: -6 }, { x: -6, y: 3 }, { x: 0, y: 0 }], duration: 0.22, ease: "none" }, t0 + 0.22);
        tl.from(`#${u}-bar`, { scaleX: 0, duration: 0.22, ease: "expo.out" }, t0 + 0.2);
      },
    },

    stack: {
      name: "Block Stack", kind: "text", desc: "Navy / red blocks stack line-by-line, sliding in from alternate sides.",
      html: (b, u) => `<div class="d-center d-stack">${(lines(b).length ? lines(b) : ["HEADLINE"]).map((l, i) => `<div class="blk ${i % 2 ? "red" : "navy"}" id="${u}-l${i}" style="font-size:${fit(l, 160, 940)}px">${esc(l)}</div>`).join("")}</div>`,
      anim: (tl, u, t0, d, b) => (lines(b).length ? lines(b) : [1]).forEach((_, i) =>
        tl.from(`#${u}-l${i}`, { xPercent: i % 2 ? 140 : -140, opacity: 0, duration: 0.3, ease: i % 2 ? "power3.out" : "expo.out" }, t0 + 0.06 + i * 0.12)),
    },

    kinetic: {
      name: "Kinetic Pop", kind: "text", desc: "Words pop one-by-one on the beat; last word turns red.",
      html: (b, u) => {
        const words = lines(b).join(" • ").split(/\s+/).filter(Boolean);
        return `<div class="d-center d-kin">${words.map((w, i) => w === "•" ? `<span class="dot" id="${u}-k${i}"></span>` : `<span class="kw${i === words.length - 1 ? " hot" : ""}" id="${u}-k${i}" style="font-size:${fit(words.reduce((a, w) => (w.length > a.length ? w : a), ""), 170, 900)}px">${esc(w)}</span>`).join("")}</div>`;
      },
      anim: (tl, u, t0, d, b) => {
        const n = lines(b).join(" • ").split(/\s+/).filter(Boolean).length || 1;
        const step = Math.min(0.32, Math.max(0.08, (d - 0.35) / n));
        for (let i = 0; i < n; i++) tl.from(`#${u}-k${i}`, { scale: 0.2, opacity: 0, duration: 0.22, ease: "back.out(3)" }, t0 + 0.05 + i * step);
      },
    },

    marker: {
      name: "Red Marker", kind: "text", desc: "White text rides up while a red marker sweeps behind it.",
      html: (b, u) => `<div class="d-center d-mark">${(lines(b).length ? lines(b) : ["HEADLINE"]).map((l, i) => `<div class="ln"><span class="hl" id="${u}-h${i}"></span><span class="tx" id="${u}-t${i}" style="font-size:${fit(l, 165, 940)}px">${esc(l)}</span></div>`).join("")}</div>`,
      anim: (tl, u, t0, d, b) => (lines(b).length ? lines(b) : [1]).forEach((_, i) => {
        tl.from(`#${u}-h${i}`, { scaleX: 0, duration: 0.28, ease: "power4.out" }, t0 + 0.05 + i * 0.14);
        tl.from(`#${u}-t${i}`, { yPercent: 70, opacity: 0, duration: 0.3, ease: "expo.out" }, t0 + 0.1 + i * 0.14);
      }),
    },

    outline: {
      name: "Outline Fill", kind: "text", desc: "Hollow outline text, then solid white fills left → right.",
      html: (b, u) => `<div class="d-center d-out">${(lines(b).length ? lines(b) : ["HEADLINE"]).map((l, i) => { const fs = fit(l, 190); return `<div class="ow" style="font-size:${fs}px"><span class="o" id="${u}-o${i}">${esc(l)}</span><span class="f" id="${u}-f${i}">${esc(l)}</span></div>`; }).join("")}</div>`,
      anim: (tl, u, t0, d, b) => (lines(b).length ? lines(b) : [1]).forEach((_, i) => {
        tl.from(`#${u}-o${i}`, { scale: 1.4, opacity: 0, duration: 0.25, ease: "power3.out" }, t0 + 0.04 + i * 0.1);
        tl.fromTo(`#${u}-f${i}`, { clipPath: "inset(0% 100% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)", duration: Math.min(0.5, d * 0.45), ease: "power2.inOut" }, t0 + 0.25 + i * 0.1);
      }),
    },

    tag: {
      name: "Academy Ribbon", kind: "text", desc: "Angled red ribbon with ★ stars (logo banner style) whips in.",
      html: (b, u) => { const t = lines(b).join("  •  ") || "UDAAN"; return `<div class="d-center d-tag"><div class="rib" id="${u}-r"><span class="shadow"></span><span class="txt" style="font-size:${fit(t + "★★", 120, 900)}px">★ ${esc(t)} ★</span></div></div>`; },
      anim: (tl, u, t0) => tl.from(`#${u}-r`, { xPercent: -160, skewX: -25, duration: 0.32, ease: "expo.out" }, t0 + 0.04),
    },

    stamp: {
      name: "Badge Stamp", kind: "text", desc: "Round navy badge spins + stamps down with a red ring pulse.",
      html: (b, u) => { const L = lines(b).length ? lines(b) : ["BADGE"]; return `<div class="d-center"><div class="d-stamp" id="${u}-s"><span class="ring" id="${u}-ring"></span>${L.map((l) => `<div style="font-size:${fit(l, 150, 420)}px">${esc(l)}</div>`).join("")}</div></div>`; },
      anim: (tl, u, t0) => {
        tl.from(`#${u}-s`, { scale: 3, rotation: -200, opacity: 0, duration: 0.3, ease: "power4.in" }, t0 + 0.04);
        tl.fromTo(`#${u}-ring`, { scale: 1, opacity: 0.9 }, { scale: 1.6, opacity: 0, duration: 0.45, ease: "power2.out" }, t0 + 0.34);
      },
    },
  };

  // =====================================================================
  // ACCENT GRAPHICS (no text — safe over burned-in AI text; layer on anything)
  // =====================================================================
  const ACCENTS = {
    none: { name: "None", desc: "No accent graphic.", html: () => "", anim: () => {} },

    corners: {
      name: "Frame Brackets", desc: "Four L-brackets snap in to frame the action.",
      html: (b, u) => `<div class="a-corners">${["tl", "tr", "bl", "br"].map((c) => `<i class="c-${c}" id="${u}-${c}"></i>`).join("")}</div>`,
      anim: (tl, u, t0) => ["tl", "tr", "bl", "br"].forEach((c, i) =>
        tl.from(`#${u}-${c}`, { x: c[1] === "l" ? -120 : 120, y: c[0] === "t" ? -120 : 120, opacity: 0, duration: 0.26, ease: "expo.out" }, t0 + 0.03 + i * 0.04)),
    },

    speedlines: {
      name: "Speed Lines", desc: "White + red streaks rip across the frame edges.",
      html: (b, u) => { const r = rng(hash(u)); let h = '<div class="a-speed">'; for (let i = 0; i < 12; i++) { const top = i < 6 ? 290 + r() * 380 : 1080 + r() * 420; h += `<i id="${u}-s${i}" class="${i % 3 === 0 ? "red" : ""}" style="top:${top.toFixed(0)}px;width:${(240 + r() * 420).toFixed(0)}px;height:${(5 + r() * 9).toFixed(0)}px"></i>`; } return h + "</div>"; },
      anim: (tl, u, t0, d) => { const r = rng(hash(u) + 7); for (let i = 0; i < 12; i++) tl.fromTo(`#${u}-s${i}`, { x: -900 }, { x: 1500, duration: 0.3 + r() * 0.25, ease: "power2.in" }, t0 + r() * Math.min(0.5, d * 0.5)); },
    },

    balltrail: {
      name: "Ball Trail", desc: "A red cricket ball zips across on an arc with a motion trail.",
      html: (b, u) => `<div class="a-ball">${[5, 4, 3, 2, 1, 0].map((k) => `<i class="ball${k ? " ghost" : ""}" id="${u}-b${k}" style="opacity:${k ? (0.5 - k * 0.08).toFixed(2) : 1}"></i>`).join("")}</div>`,
      anim: (tl, u, t0, d) => { const D = Math.min(0.7, Math.max(0.4, d * 0.6)); [5, 4, 3, 2, 1, 0].forEach((k) => {
        tl.fromTo(`#${u}-b${k}`, { x: -160 }, { x: 1240, duration: D, ease: "none" }, t0 + 0.05 + k * 0.025);
        tl.fromTo(`#${u}-b${k}`, { y: 1350 }, { y: 520, duration: D, ease: "power2.out" }, t0 + 0.05 + k * 0.025);
        tl.fromTo(`#${u}-b${k}`, { rotation: 0 }, { rotation: 900, duration: D, ease: "none" }, t0 + 0.05 + k * 0.025); }); },
    },

    slashes: {
      name: "Sport Slashes", desc: "Diagonal red / navy bars slice in from the corners.",
      html: (b, u) => `<div class="a-slash"><i class="s1" id="${u}-x1"></i><i class="s2" id="${u}-x2"></i><i class="s3" id="${u}-x3"></i></div>`,
      anim: (tl, u, t0) => {
        tl.from(`#${u}-x1`, { xPercent: -130, duration: 0.28, ease: "expo.out" }, t0 + 0.03);
        tl.from(`#${u}-x2`, { xPercent: 130, duration: 0.28, ease: "power3.out" }, t0 + 0.09);
        tl.from(`#${u}-x3`, { xPercent: 130, duration: 0.3, ease: "expo.out" }, t0 + 0.14);
      },
    },

    burst: {
      name: "Impact Burst", desc: "Radial impact rays + shock ring at the cut.",
      html: (b, u) => `<div class="a-burst" id="${u}-c">${Array.from({ length: 16 }, (_, i) => `<i style="transform:rotate(${i * 22.5}deg)"><b id="${u}-r${i}" class="${i % 2 ? "red" : ""}"></b></i>`).join("")}<span class="ring" id="${u}-g"></span></div>`,
      anim: (tl, u, t0) => {
        for (let i = 0; i < 16; i++) { tl.fromTo(`#${u}-r${i}`, { scaleY: 0, y: 0, opacity: 1 }, { scaleY: 1, y: -60, duration: 0.18, ease: "expo.out" }, t0 + 0.02); tl.to(`#${u}-r${i}`, { opacity: 0, y: -240, duration: 0.22, ease: "power2.in" }, t0 + 0.2); }
        tl.fromTo(`#${u}-g`, { scale: 0.2, opacity: 1 }, { scale: 3.2, opacity: 0, duration: 0.45, ease: "power2.out" }, t0 + 0.02);
      },
    },

    shine: {
      name: "Light Sweep", desc: "A diagonal light glint sweeps across the shot.",
      html: (b, u) => `<div class="a-shine"><i id="${u}-sh"></i></div>`,
      anim: (tl, u, t0, d) => tl.fromTo(`#${u}-sh`, { xPercent: -160 }, { xPercent: 260, duration: Math.min(0.8, d * 0.7), ease: "power2.inOut" }, t0 + 0.08),
    },

    pulse: {
      name: "Beat Pulse", desc: "Red edge vignette pulses on the cut (heartbeat energy).",
      html: (b, u) => `<div class="a-pulse" id="${u}-p"></div>`,
      anim: (tl, u, t0) => tl.fromTo(`#${u}-p`, { opacity: 0.95 }, { opacity: 0, duration: 0.45, ease: "power2.out" }, t0 + 0.02),
    },
  };

  // =====================================================================
  // SHOT MOTION (applied to the shot's motion layer — never to <video> itself)
  // =====================================================================
  const MOTIONS = {
    none: { name: "Static", anim: () => {} },
    punch: { name: "Punch-in", anim: (tl, s, t0) => tl.fromTo(s, { scale: 1.16 }, { scale: 1, duration: 0.32, ease: "expo.out" }, t0) },
    push: { name: "Slow push", anim: (tl, s, t0, d) => tl.fromTo(s, { scale: 1 }, { scale: 1.1, duration: d, ease: "none" }, t0) },
    pull: { name: "Pull out", anim: (tl, s, t0, d) => tl.fromTo(s, { scale: 1.14 }, { scale: 1, duration: d, ease: "power1.out" }, t0) },
    drift: { name: "Drift", anim: (tl, s, t0, d) => tl.fromTo(s, { scale: 1.1, x: -40 }, { scale: 1.1, x: 40, duration: d, ease: "none" }, t0) },
    shake: { name: "Punch + shake", anim: (tl, s, t0) => { tl.fromTo(s, { scale: 1.2 }, { scale: 1.04, duration: 0.25, ease: "expo.out" }, t0); tl.fromTo(s, { x: 0, y: 0 }, { keyframes: [{ x: 14, y: -8 }, { x: -12, y: 6 }, { x: 8, y: 4 }, { x: -4, y: -2 }, { x: 0, y: 0 }], duration: 0.3, ease: "none" }, t0 + 0.02); } },
  };

  // =====================================================================
  // TRANSITIONS INTO a beat (fire at the beat's start)
  // =====================================================================
  const TRANSITIONS = {
    cut: { name: "Hard cut", html: () => "", anim: () => {} },
    flash: { name: "White flash", html: (u) => `<div class="t-flash" id="${u}-fl"></div>`,
      anim: (tl, u, t0) => { tl.fromTo(`#${u}-fl`, { opacity: 0 }, { opacity: 0.9, duration: 0.06, ease: "none" }, Math.max(0, t0 - 0.06)); tl.to(`#${u}-fl`, { opacity: 0, duration: 0.25, ease: "power2.out" }, t0); } },
    whip: { name: "Whip pan", html: (u) => `<div class="t-streak" id="${u}-st"></div>`,
      anim: (tl, u, t0, w) => { tl.fromTo(w, { xPercent: 100, filter: "blur(24px)" }, { xPercent: 0, filter: "blur(0px)", duration: 0.2, ease: "power3.out" }, t0); tl.fromTo(`#${u}-st`, { xPercent: -100, opacity: 1 }, { xPercent: 100, opacity: 0, duration: 0.25, ease: "power2.out" }, t0); } },
    redwipe: { name: "Red wipe", html: (u) => `<div class="t-wipe"><i class="r" id="${u}-wr"></i><i class="n" id="${u}-wn"></i></div>`,
      anim: (tl, u, t0) => { tl.fromTo(`#${u}-wr`, { xPercent: -110 }, { xPercent: 110, duration: 0.34, ease: "power3.inOut" }, Math.max(0, t0 - 0.17)); tl.fromTo(`#${u}-wn`, { xPercent: -110 }, { xPercent: 110, duration: 0.34, ease: "power3.inOut" }, Math.max(0, t0 - 0.12)); } },
    zoom: { name: "Zoom punch", html: (u) => `<div class="t-flash soft" id="${u}-zf"></div>`,
      anim: (tl, u, t0, w) => { tl.fromTo(w, { scale: 1.5, filter: "blur(18px)" }, { scale: 1, filter: "blur(0px)", duration: 0.26, ease: "expo.out" }, t0); tl.fromTo(`#${u}-zf`, { opacity: 0.5 }, { opacity: 0, duration: 0.25, ease: "power2.out" }, t0); } },
    glitch: { name: "Glitch", html: (u) => `<div class="t-glitch">${[0, 1, 2, 3, 4].map((i) => `<i id="${u}-g${i}" class="${i % 2 ? "red" : ""}" style="top:${300 + i * 290}px;height:${30 + (i % 3) * 26}px"></i>`).join("")}</div>`,
      anim: (tl, u, t0, w) => { tl.fromTo(w, { x: 0 }, { keyframes: [{ x: 40 }, { x: -30 }, { x: 18 }, { x: 0 }], duration: 0.16, ease: "none" }, t0); for (let i = 0; i < 5; i++) tl.fromTo(`#${u}-g${i}`, { opacity: 0.85, x: i % 2 ? 60 : -60 }, { opacity: 0, x: 0, duration: 0.18, ease: "steps(3)" }, t0 + i * 0.015); } },
  };

  // Suggestions — every beat gets at least 3 designs to choose from.
  function suggest(b) {
    const hasText = lines(b).length > 0;
    if (b.burned) return { designs: ["none", "tag", "stamp"], accents: ["corners", "shine", "speedlines", "pulse"] };
    if (hasText) {
      const n = lines(b).join(" ").length;
      return { designs: n <= 8 ? ["slam", "kinetic", "outline", "stamp", "tag"] : ["stack", "marker", "kinetic", "tag", "outline"], accents: ["burst", "speedlines", "slashes", "pulse"] };
    }
    return { designs: ["none", "kinetic", "tag", "slam"], accents: ["balltrail", "speedlines", "slashes", "corners", "burst", "shine", "pulse"] };
  }

  // =====================================================================
  // MARKUP + TIMELINE
  // =====================================================================
  const fx = (f) => { f = f || {}; return { x: f.x == null ? 50 : f.x, y: f.y == null ? 50 : f.y, z: f.zoom || 1 }; };
  function videoBlock(id, u, src, inPt, start, dur, track, f, grade, base, cls) {
    const F = fx(f);
    return `<div class="vw${cls ? " " + cls : ""}" id="w-${id}"><div class="vm" id="m-${id}"><div class="vf" style="transform:scale(${F.z});transform-origin:${F.x}% ${F.y}%">` +
      `<video id="v-${id}" src="${base}${src}" data-start="${start.toFixed(3)}" data-duration="${dur.toFixed(3)}" data-media-start="${(+inPt).toFixed(3)}" data-track-index="${track}" muted playsinline preload="auto" style="object-position:${F.x}% ${F.y}%${grade ? ";filter:contrast(1.07) saturate(1.15)" : ""}"></video></div></div></div>`;
  }

  function markup(P, base) {
    base = base || "";
    const B = withDur(P); let h = "";
    B.forEach((b, i) => {
      const u = b.id, s = b.start, d = b.dur, split = b.layout === "split";
      if (split) h += `<div class="clip split-bg" id="sb-${u}" data-start="${s.toFixed(3)}" data-duration="${d.toFixed(3)}" data-track-index="3"></div>`;
      h += videoBlock(u, u, b.src, b.in, s, d, i % 2, b.fit, b.grade, base, split ? "half top" : "");
      if (split) {
        const d2 = Math.max(0.1, d - (b.delay2 || 0));
        h += videoBlock(u + "b", u, b.src2, b.in2 || 0, s + (b.delay2 || 0), d2, 2, b.fit2, b.grade2, base, "half bot");
        h += `<div class="clip split-line" id="sl-${u}" data-start="${s.toFixed(3)}" data-duration="${d.toFixed(3)}" data-track-index="4"></div>`;
      }
      const D = DESIGNS[b.design] || DESIGNS.none, A = ACCENTS[b.accent] || ACCENTS.none;
      h += `<div class="clip ov" id="o-${u}" data-start="${s.toFixed(3)}" data-duration="${d.toFixed(3)}" data-track-index="${10 + (i % 2)}">${A.html(b, u + "a")}${D.html(b, u + "d")}</div>`;
      const T = TRANSITIONS[b.trans] || TRANSITIONS.cut;
      if (T.html(u)) h += `<div class="clip tr" id="t-${u}" data-start="${Math.max(0, s - 0.2).toFixed(3)}" data-duration="0.55" data-track-index="${12 + (i % 2)}">${T.html(u + "t")}</div>`;
      if (b.patch) { const p = b.patch, ps = s + (p.from || 0); h += `<div class="clip patch" id="p-${u}" data-start="${ps.toFixed(3)}" data-duration="${(s + d - ps).toFixed(3)}" data-track-index="14" style="left:${p.x}px;top:${p.y}px;width:${p.w}px;height:${p.h}px;background:${p.color}"></div>`; }
    });
    h += `<img id="logo" class="clip" src="${base}${P.meta.logo}" alt="Udaan Cricket Academy" data-start="0" data-duration="${P.meta.duration.toFixed(3)}" data-track-index="20">`;
    return h;
  }

  function buildTimeline(tl, P) {
    withDur(P).forEach((b) => {
      const u = b.id, t0 = b.start, d = b.dur;
      (MOTIONS[b.motion] || MOTIONS.none).anim(tl, `#m-${u}`, t0, d);
      if (b.layout === "split") {
        tl.from(`#w-${u}`, { xPercent: -100, duration: 0.32, ease: "expo.out" }, t0);
        tl.from(`#w-${u}b`, { xPercent: 100, duration: 0.32, ease: "expo.out" }, t0 + (b.delay2 || 0));
        tl.from(`#sl-${u}`, { scaleX: 0, duration: 0.35, ease: "power3.inOut" }, t0 + 0.1);
        (MOTIONS[b.motion2 || "push"] || MOTIONS.none).anim(tl, `#m-${u}b`, t0 + (b.delay2 || 0), Math.max(0.1, d - (b.delay2 || 0)));
      }
      const T = TRANSITIONS[b.trans] || TRANSITIONS.cut;
      if (b.layout !== "split") T.anim(tl, u + "t", t0, `#w-${u}`);
      else if (T.html(u)) T.anim(tl, u + "t", t0, `#sb-${u}`);
      (ACCENTS[b.accent] || ACCENTS.none).anim(tl, u + "a", t0, d, b);
      (DESIGNS[b.design] || DESIGNS.none).anim(tl, u + "d", t0, d, b);
    });
    tl.from("#logo", { scale: 0.5, opacity: 0, duration: 0.5, ease: "back.out(2)" }, 0.1);
    return tl;
  }

  function css(base) {
    base = base || "";
    return `
@font-face{font-family:"Barlow Condensed";font-weight:700;src:url("${base}assets/fonts/barlow-condensed-latin-700-normal.woff2") format("woff2");}
@font-face{font-family:"Barlow Condensed";font-weight:800;src:url("${base}assets/fonts/barlow-condensed-latin-800-normal.woff2") format("woff2");}
#root{position:relative;width:1080px;height:1920px;overflow:hidden;background:${NAVY};font-family:"Barlow Condensed",sans-serif;}
#root *{box-sizing:border-box;}
.vw{position:absolute;inset:0;overflow:hidden;transform-origin:50% 50%;}
.vm,.vf{position:absolute;inset:0;transform-origin:50% 50%;}
.vw video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;}
.vw.half{top:0;bottom:auto;height:960px;z-index:5;} .vw.half.bot{top:960px;}
.split-bg{position:absolute;inset:0;background:${NAVY};z-index:4;}
.split-line{position:absolute;left:0;top:950px;width:1080px;height:20px;background:${RED};box-shadow:0 0 0 5px #fff;transform-origin:0 50%;z-index:6;}
.ov{position:absolute;inset:0;z-index:30;pointer-events:none;}
.tr{position:absolute;inset:0;z-index:40;pointer-events:none;}
.patch{position:absolute;z-index:29;}
#logo{position:absolute;top:60px;right:40px;width:200px;height:auto;z-index:50;filter:drop-shadow(0 6px 14px rgba(0,0,0,.45));}
/* text zone: y 640–1460 (clear of logo + Reels UI) */
.d-center{position:absolute;left:60px;right:60px;top:640px;height:820px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;text-align:center;}
.d-slam .w{color:#fff;font-weight:800;line-height:.9;text-transform:uppercase;letter-spacing:2px;text-shadow:0 10px 0 ${NAVY},0 18px 40px rgba(0,0,0,.6);}
.d-slam .bar{width:62%;height:22px;background:${RED};transform:skewX(-20deg);box-shadow:0 8px 20px rgba(0,0,0,.4);}
.d-stack .blk{color:#fff;font-weight:800;line-height:1;padding:16px 30px 12px;text-transform:uppercase;box-shadow:0 10px 30px rgba(0,0,0,.4);}
.d-stack .navy{background:${NAVY};} .d-stack .red{background:${RED};}
.d-kin{flex-direction:row;flex-wrap:wrap;gap:10px 22px;}
.d-kin .kw{display:inline-block;color:#fff;font-weight:800;line-height:1;text-transform:uppercase;padding:10px 22px 6px;background:${NAVY};box-shadow:0 10px 26px rgba(0,0,0,.45);}
.d-kin .kw.hot{background:${RED};}
.d-kin .dot{display:inline-block;width:22px;height:22px;border-radius:50%;background:#fff;box-shadow:0 2px 10px rgba(0,0,0,.5);}
.d-mark .ln{position:relative;padding:6px 26px;}
.d-mark .hl{position:absolute;inset:8px 0 2px 0;background:${RED};transform-origin:0 50%;transform:skewX(-8deg);}
.d-mark .tx{position:relative;display:inline-block;color:#fff;font-weight:800;line-height:1.02;text-transform:uppercase;}
.d-out .ow{position:relative;font-weight:800;line-height:.95;text-transform:uppercase;}
.d-out .o{color:transparent;-webkit-text-stroke:5px #fff;display:inline-block;}
.d-out .f{position:absolute;left:0;top:0;color:#fff;text-shadow:0 8px 0 ${RED};}
.d-tag .rib{position:relative;transform:rotate(-4deg);}
.d-tag .shadow{position:absolute;inset:0;background:${NAVY};transform:translate(14px,14px);}
.d-tag .txt{position:relative;display:block;background:${RED};color:#fff;font-weight:800;line-height:1;padding:20px 40px 14px;text-transform:uppercase;white-space:nowrap;border:5px solid #fff;}
.d-stamp{position:relative;width:520px;height:520px;border-radius:50%;background:${NAVY};border:12px solid #fff;outline:10px solid ${RED};display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-weight:800;line-height:1;text-transform:uppercase;box-shadow:0 20px 50px rgba(0,0,0,.5);}
.d-stamp .ring{position:absolute;inset:-40px;border-radius:50%;border:10px solid ${RED};}
.a-corners i{position:absolute;width:150px;height:150px;border:0 solid #fff;}
.a-corners .c-tl{left:56px;top:300px;border-left-width:14px;border-top-width:14px;}
.a-corners .c-tr{right:56px;top:300px;border-right-width:14px;border-top-width:14px;border-color:${RED};}
.a-corners .c-bl{left:56px;bottom:420px;border-left-width:14px;border-bottom-width:14px;border-color:${RED};}
.a-corners .c-br{right:56px;bottom:420px;border-right-width:14px;border-bottom-width:14px;}
.a-speed i{position:absolute;left:0;background:linear-gradient(90deg,rgba(255,255,255,0),#fff);border-radius:8px;}
.a-speed i.red{background:linear-gradient(90deg,rgba(215,25,42,0),${RED});}
.a-ball .ball{position:absolute;left:0;top:0;width:96px;height:96px;margin:-48px 0 0 -48px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ff6b6b,${RED} 45%,#7a0a12);box-shadow:0 6px 20px rgba(0,0,0,.5);}
.a-ball .ball::after{content:"";position:absolute;left:44px;top:4px;width:8px;height:88px;border-left:3px dashed rgba(255,255,255,.85);border-right:3px dashed rgba(255,255,255,.85);}
.a-ball .ghost{filter:blur(4px);}
.a-slash i{position:absolute;height:70px;transform:skewY(-12deg);}
.a-slash .s1{left:-60px;top:330px;width:620px;background:${RED};}
.a-slash .s2{right:-60px;top:420px;width:380px;height:26px;background:#fff;}
.a-slash .s3{right:-60px;bottom:470px;width:640px;background:${NAVY};border-top:8px solid ${RED};}
.a-burst{position:absolute;left:540px;top:1000px;width:0;height:0;}
.a-burst i{position:absolute;left:0;top:0;width:0;height:0;}
.a-burst b{position:absolute;left:-7px;top:-460px;width:14px;height:220px;background:#fff;border-radius:7px;transform-origin:50% 100%;}
.a-burst b.red{background:${RED};}
.a-burst .ring{position:absolute;left:-150px;top:-150px;width:300px;height:300px;border-radius:50%;border:14px solid #fff;}
.a-shine i{position:absolute;top:-300px;left:0;width:360px;height:2600px;transform:rotate(18deg);background:linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,.55),rgba(255,255,255,0));mix-blend-mode:screen;}
.a-pulse{position:absolute;inset:0;box-shadow:inset 0 0 0 26px ${RED},inset 0 0 220px 40px rgba(215,25,42,.65);}
.t-flash{position:absolute;inset:0;background:#fff;opacity:0;} .t-flash.soft{background:#fff;}
.t-streak{position:absolute;inset:0;background:linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,.75) 50%,rgba(255,255,255,0));filter:blur(10px);}
.t-wipe i{position:absolute;top:-100px;bottom:-100px;width:140%;left:-20%;transform:skewX(-14deg);}
.t-wipe .r{background:${RED};} .t-wipe .n{background:${NAVY};}
.t-glitch i{position:absolute;left:0;width:100%;background:rgba(255,255,255,.85);opacity:0;mix-blend-mode:screen;}
.t-glitch i.red{background:${RED};}
`;
  }

  const API = { DESIGNS, ACCENTS, MOTIONS, TRANSITIONS, suggest, markup, buildTimeline, css, withDur, lines };
  if (typeof module !== "undefined" && module.exports) module.exports = API;
  else root.UdaanDesigns = API;
})(typeof window !== "undefined" ? window : globalThis);
